m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0475');owned=set(m['owned_words'])
R=[dict(id='C0475',meaning='生出；出身；种类；天性',core='从一个来源生出来，带着来源关系或原有性质',image='一边是一代人生出下一代，一边是过程产生新东西；出身、种类、天赋等词义沿不同支线分开。',intro='拉丁 gignere 是生出、产生，genitus 是相关分词；genus、gener- 说出身与种类。于是 generation 可说代际和产出，genius 走向天赋，gentle 经过氏族、出身与礼仪的历史才变成温柔。每条支线都有自己的经历，不能只用“生”硬翻所有单词。',forms='gener- 来自 genus 的词干变化；gent- 接 gēns“氏族”；genit- 接 genitus。ingenious 与 ingenuous 都有古老出生词根，却沿不同拉丁词发展；ingenuity 的现代意义还受二者历史混用影响。',branches=[['产生与再生','generate、generation、generator、generative、generational、intergenerational、regenerate、regeneration、regenerative、cogeneration、engender'],['出身、后代与生殖','indigenous、progeny、primogenitor、genital、genitalia、congenital'],['天性与真伪','genius、genuine、genuinely、genuineness、ingenious、ingeniously、ingenuous、disingenuous、ingenuity'],['举止与相处','gentle、gently、gentleness、gentleman、gentlewoman、genteel、genial、congenial、congeniality、generous、generosity'],['种类与语法','genus、generic、genre、gender、genitive']],contrasts='ingenious 是巧妙，ingenuous 是天真坦率，disingenuous 是不坦诚。congenial 是投缘，congenital 是先天。genial 的颏部义与 gender 的印尼乐器义另有来源，不能塞进出生这条线。',practice='用 generate 说一种产出，用 generation 说一代人。再分别写 ingenious solution、ingenuous question、genuine concern，体会巧思、坦率和真实性三个不同观察角度。',words=list(family),sources=['https://www.etymonline.com/word/generation','https://www.etymonline.com/word/gentle','https://www.etymonline.com/word/ingenuity'])]
assert {w['word'] for w in W}==set(family)&owned,((set(family)&owned)-{w['word'] for w in W})
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa']
